-- Capability roles. They have NOLOGIN and contain no passwords.
-- Membership for the actual Termux worker/dashboard logins is an explicit operator step.
BEGIN;
DO $$ BEGIN
 BEGIN CREATE ROLE marketmind_worker NOLOGIN; EXCEPTION WHEN duplicate_object OR unique_violation THEN NULL; END;
 BEGIN CREATE ROLE marketmind_api_reader NOLOGIN; EXCEPTION WHEN duplicate_object OR unique_violation THEN NULL; END;
END $$;
GRANT USAGE ON SCHEMA public TO marketmind_worker,marketmind_api_reader;
GRANT SELECT,INSERT,UPDATE,DELETE ON TABLE public.adaptive_battle_configs,public.adaptive_battle_snapshots,public.adaptive_paper_accounts,public.adaptive_paper_equity_snapshots,public.adaptive_paper_positions,public.adaptive_paper_trades,public.adaptive_position_sizing_snapshots,public.adaptive_weight_advisor_snapshots,public.ai_decision_v2_snapshots,public.btc_liquidation_snapshots,public.btc_open_interest_snapshots,public.context_activation_snapshots,public.context_decision_gate_snapshots,public.context_execution_guard_snapshots,public.context_execution_outcome_snapshots,public.context_performance_snapshots,public.context_promotion_snapshots,public.context_rollback_snapshots,public.context_tuning_candidates,public.estimated_liquidation_levels,public.estimated_liquidation_maps,public.etf_flow_details,public.etf_flow_price_responses,public.etf_flow_snapshots,public.etf_scores,public.final_market_backtests,public.final_market_decisions,public.final_market_performance,public.funding_snapshots,public.global_futures_exchange_snapshots,public.global_futures_snapshots,public.long_term_trend_snapshots,public.market_candles,public.market_context_snapshots,public.market_correlation_snapshots,public.market_intelligence_scores,public.market_regime_snapshots,public.market_scores,public.market_structure_snapshots,public.news_articles,public.news_scores,public.onchain_snapshots,public.paper_equity_snapshots,public.paper_positions,public.paper_strategy_configs,public.paper_strategy_runs,public.paper_trades,public.paper_trading_accounts,public.performance_battle_snapshots,public.phase7_pipeline_audit_snapshots,public.position_cluster_levels,public.position_cluster_maps,public.shadow_signal_validation_snapshots,public.signal_calibration_snapshots,public.squeeze_early_warning_snapshots,public.squeeze_opportunity_snapshots,public.squeeze_probability_snapshots,public.strategy_candidate_comparisons,public.strategy_optimization_status,public.strategy_performance_snapshots,public.strategy_recommendations,public.strategy_validation_results,public.technical_snapshots,public.worker_execution_locks,public.worker_execution_runs,public.worker_execution_stages TO marketmind_worker;
GRANT SELECT ON TABLE public.adaptive_battle_configs,public.adaptive_battle_snapshots,public.adaptive_paper_accounts,public.adaptive_paper_equity_snapshots,public.adaptive_paper_positions,public.adaptive_paper_trades,public.adaptive_position_sizing_snapshots,public.adaptive_weight_advisor_snapshots,public.ai_decision_v2_snapshots,public.btc_liquidation_snapshots,public.btc_open_interest_snapshots,public.context_activation_snapshots,public.context_decision_gate_snapshots,public.context_execution_guard_snapshots,public.context_execution_outcome_snapshots,public.context_performance_snapshots,public.context_promotion_snapshots,public.context_rollback_snapshots,public.context_tuning_candidates,public.estimated_liquidation_levels,public.estimated_liquidation_maps,public.etf_flow_details,public.etf_flow_price_responses,public.etf_flow_snapshots,public.etf_scores,public.final_market_backtests,public.final_market_decisions,public.final_market_performance,public.funding_snapshots,public.global_futures_exchange_snapshots,public.global_futures_snapshots,public.long_term_trend_snapshots,public.market_candles,public.market_context_snapshots,public.market_correlation_snapshots,public.market_intelligence_scores,public.market_regime_snapshots,public.market_scores,public.market_structure_snapshots,public.news_articles,public.news_scores,public.onchain_snapshots,public.paper_equity_snapshots,public.paper_positions,public.paper_strategy_configs,public.paper_strategy_runs,public.paper_trades,public.paper_trading_accounts,public.performance_battle_snapshots,public.phase7_pipeline_audit_snapshots,public.position_cluster_levels,public.position_cluster_maps,public.shadow_signal_validation_snapshots,public.signal_calibration_snapshots,public.squeeze_early_warning_snapshots,public.squeeze_opportunity_snapshots,public.squeeze_probability_snapshots,public.strategy_candidate_comparisons,public.strategy_optimization_status,public.strategy_performance_snapshots,public.strategy_recommendations,public.strategy_validation_results,public.technical_snapshots,public.worker_execution_locks,public.worker_execution_runs,public.worker_execution_stages,public.latest_strategy_performance,public.latest_strategy_candidate_comparisons,public.latest_strategy_validation_results,public.latest_strategy_recommendation,public.latest_strategy_optimization_status,public.paper_strategy_comparison_v1 TO marketmind_api_reader;
DO $$ DECLARE seq text; tab text; BEGIN
 FOREACH tab IN ARRAY ARRAY['adaptive_battle_configs','adaptive_battle_snapshots','adaptive_paper_accounts','adaptive_paper_equity_snapshots','adaptive_paper_positions','adaptive_paper_trades','adaptive_position_sizing_snapshots','adaptive_weight_advisor_snapshots','ai_decision_v2_snapshots','btc_liquidation_snapshots','btc_open_interest_snapshots','context_activation_snapshots','context_decision_gate_snapshots','context_execution_guard_snapshots','context_execution_outcome_snapshots','context_performance_snapshots','context_promotion_snapshots','context_rollback_snapshots','context_tuning_candidates','estimated_liquidation_levels','estimated_liquidation_maps','etf_flow_details','etf_flow_price_responses','etf_flow_snapshots','etf_scores','final_market_backtests','final_market_decisions','final_market_performance','funding_snapshots','global_futures_exchange_snapshots','global_futures_snapshots','long_term_trend_snapshots','market_context_snapshots','market_correlation_snapshots','market_intelligence_scores','market_regime_snapshots','market_scores','market_structure_snapshots','news_articles','news_scores','onchain_snapshots','paper_equity_snapshots','paper_positions','paper_strategy_configs','paper_strategy_runs','paper_trades','paper_trading_accounts','performance_battle_snapshots','phase7_pipeline_audit_snapshots','position_cluster_levels','position_cluster_maps','shadow_signal_validation_snapshots','signal_calibration_snapshots','squeeze_early_warning_snapshots','squeeze_opportunity_snapshots','squeeze_probability_snapshots','strategy_candidate_comparisons','strategy_optimization_status','strategy_performance_snapshots','strategy_recommendations','strategy_validation_results','technical_snapshots','worker_execution_runs','worker_execution_stages'] LOOP
  seq:=pg_get_serial_sequence('public.'||quote_ident(tab),'id');
  IF seq IS NOT NULL THEN EXECUTE format('GRANT USAGE,SELECT ON SEQUENCE %s TO marketmind_worker',seq); END IF;
 END LOOP;
END $$;
DO $$ DECLARE f record; BEGIN
 FOR f IN SELECT p.oid::regprocedure signature FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
 WHERE n.nspname='public' AND p.proname IN('acquire_worker_lock_v2','heartbeat_worker_lock_v2','release_worker_lock_v2','mark_stale_worker_runs_v1','paper_open_position_v1','paper_close_position_v1','adaptive_paper_open_position_v1','adaptive_paper_close_position_v1') LOOP
 EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO marketmind_worker',f.signature);
 EXECUTE format('REVOKE ALL ON FUNCTION %s FROM marketmind_api_reader',f.signature);
 END LOOP;
END $$;
COMMIT;
